import express from 'express';
import bodyParser from 'body-parser';
import cors from 'cors';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import path from 'path';
import { initializeDatabase, getPool } from './db.js';
import usersRoutes from './routes/users.js';
import bookingsRoutes from './routes/bookings.js';
import guestBookingsRoutes from './routes/guest_bookings.js';
import emailRoutes from './routes/email_routes.js';
// Guest email routes are now integrated into the main email routes
import dotenv from 'dotenv';

dotenv.config();

const app = express();
const PORT = process.env.PORT || 8080;

// Security headers
app.use(helmet());

// Rate limiting
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 300,
  standardHeaders: true,
  legacyHeaders: false,
  message: { message: 'Too many requests, please try again later.' }
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  standardHeaders: true,
  legacyHeaders: false,
  message: { message: 'Too many login or signup attempts, please try again later.' }
});

app.use(globalLimiter);

const allowedOrigins = [
  'http://localhost:3000',
  'https://tayandtoscorporations.com'
];

app.use(cors({
  origin: function(origin, callback){
    if(!origin) return callback(null, true);
    if(allowedOrigins.indexOf(origin) === -1){
      const msg = 'The CORS policy for this site does not allow access from the specified Origin.';
      return callback(new Error(msg), false);
    }
    return callback(null, true);
  },
  credentials: true
}));
app.use(bodyParser.json());


// Initialize database and start server
async function startServer() {
    try {
        console.log('Initializing database...');
        await initializeDatabase();
        console.log('Database initialized successfully');

        // Set up database pool in app.locals
        app.locals.pool = getPool();
        console.log('Database pool initialized');

        // Mount routes
        app.use('/users/login', authLimiter);
        app.use('/users/signup', authLimiter);
        app.use('/users', usersRoutes);
        app.use('/bookings', bookingsRoutes);
        app.use('/guest_bookings', guestBookingsRoutes);
        app.use('/email', emailRoutes);
        // Guest email routes are now handled by /email/send-guest-booking-confirmation
        // Health check endpoint
        app.get('/health', (req, res) => {
            res.status(200).json({ status: 'OK' });
        });

        // Database connection test endpoint
        app.get('/db-status', async (req, res) => {
            try {
                const pool = app.locals.pool;
                const [rows] = await pool.query('SELECT 1');
                res.status(200).json({ database: 'connected' });
            } catch (err) {
                res.status(500).json({ database: 'disconnected', error: err.message });
            }
        });

        // Debug endpoint to list all routes
        app.get('/debug/routes', (req, res) => {
            const routes = [];
            app._router.stack.forEach(middleware => {
                if (middleware.route) {
                    routes.push({
                        path: middleware.route.path,
                        methods: Object.keys(middleware.route.methods)
                    });
                } else if (middleware.name === 'router') {
                    middleware.handle.stack.forEach(handler => {
                        if (handler.route) {
                            routes.push({
                                path: '/bookings' + handler.route.path,
                                methods: Object.keys(handler.route.methods)
                            });
                        }
                    });
                }
            });
            res.json({ routes });
        });

        // Error handling middleware
        app.use((err, req, res, next) => {
            console.error('Error:', err.stack);
            res.status(500).json({ error: 'Something went wrong!', details: err.message });
        });

        app.listen(PORT, '0.0.0.0', () => {
            console.log(`Server running on port ${PORT}`);
        });

    } catch (error) {
        console.error('Failed to start server:', error);
        process.exit(1);
    }
}

startServer();

// Handle graceful shutdown
process.on('SIGTERM', async () => {
    console.log('SIGTERM received. Shutting down gracefully...');
    const pool = app.locals.pool;
    await pool.end();
    process.exit(0);
});

process.on('SIGINT', async () => {
    console.log('SIGINT received. Shutting down gracefully...');
    const pool = app.locals.pool;
    await pool.end();
    process.exit(0);
});

import express from 'express';
import { getPool, query } from '../db.js';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import validator from 'validator';
import { authenticateToken, getJwtSecret } from '../middleware/auth.js';
import { sendNewUserConfirmationEmail, sendPasswordResetEmail, sendPasswordResetConfirmationEmail } from '../sevices/email_service.js';
import { generatePasswordResetToken, hashToken } from '../utils/securityUtils.js';

const router = express.Router();


router.post('/signup', async (req, res) => {
  try {
    const { email, first_name, last_name, phone_number, password } = req.body;

    // Validate required fields
    if (!email || !first_name || !last_name || !phone_number || !password) {
      return res.status(400).json({ message: 'All fields are required' });
    }

    // Check for existing email
    const [existingUsers] = await query('SELECT * FROM users WHERE email = ?', [email]);
    if (existingUsers.length > 0) {
      return res.status(400).json({ message: 'Email already exists' });
    }

    // Hash password
    const hashedPassword = await bcrypt.hash(password, 10);

    // Insert user
    const [result] = await query(
      `INSERT INTO users (email, first_name, last_name, phone_number, password_hash, admin) 
       VALUES (?, ?, ?, ?, ?, false)`,
      [email, first_name, last_name, phone_number, hashedPassword]
    );

    const newUser = {
      id: result.insertId,
      email,
      first_name,
      last_name,
      phone_number,
      admin: false
    };

    // Generate token
    const token = jwt.sign(
      { userId: newUser.id, email: newUser.email, admin: newUser.admin },
      getJwtSecret(),
      { expiresIn: '24h' }
    );

    // Send confirmation email
    try {
      await sendNewUserConfirmationEmail(newUser);
      console.log(`Confirmation email sent to ${newUser.email}`);
    } catch (emailError) {
      console.error('Error sending confirmation email:', emailError);
      // Don't fail the signup if email fails, but log the error
    }

    res.status(201).json({
      message: 'User created successfully. A confirmation email has been sent to your email address.',
      user: newUser,
      token
    });

  } catch (error) {
    console.error('Signup error:', error);
    res.status(500).json({ message: 'Error creating user' });
  }
});


// Public routes
router.post('/login', async (req, res) => {
    try {
      const { email, password } = req.body;
  
      if (!email || !password) {
        return res.status(400).json({ message: 'Email and password are required' });
      }
  
      const [users] = await query('SELECT * FROM users WHERE email = ?', [email]);
      const user = users[0];
  
      if (!user) {
        return res.status(401).json({ message: 'Invalid email or password' });
      }
  
      const validPassword = await bcrypt.compare(password, user.password_hash);
      if (!validPassword) {
        return res.status(401).json({ message: 'Invalid email or password' });
      }
  
      const token = jwt.sign(
        { userId: user.id, email: user.email, admin: user.admin },
        getJwtSecret(),
        { expiresIn: '24h' }
      );
  
      res.json({
        message: 'Login successful',
        user: {
          id: user.id,
          email: user.email,
          first_name: user.first_name,
          last_name: user.last_name,
          phone_number: user.phone_number,
          admin: user.admin
        },
        token
      });
    } catch (error) {
      console.error('Login error:', error);
      res.status(500).json({ message: 'Error logging in' });
    }
  });


// Fetch all users
router.get('/', authenticateToken, async (req, res) => {
    try {
      if (!req.user?.admin) {
        return res.status(403).json({ message: 'Only admins can access all users' });
      }
  
      console.log('Fetching users...');
      const [users] = await query(
        `SELECT 
           u.id, u.email, u.first_name, u.last_name, u.phone_number, u.admin,
           (SELECT COUNT(*) FROM bookings WHERE user_id = u.id) AS booking_count
         FROM users u
         ORDER BY u.first_name ASC`
      );
      console.log('Fetched users:', users.length);
  
      res.json(users);
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({ 
        message: 'Error fetching users', 
        error: error.message,
        details: error.stack 
      });
    }
  });


// Fetch current user's profile
router.get('/profile', authenticateToken, async (req, res) => {
  try {
    const [users] = await query(
      `SELECT id, email, first_name, last_name, phone_number, admin 
       FROM users WHERE id = ?`,
      [req.user.userId]
    );

    if (users.length === 0) {
      return res.status(404).json({ message: 'User not found' });
    }

    res.json(users[0]);
  } catch (error) {
    console.error('Profile fetch error:', error);
    res.status(500).json({ message: 'Error fetching user profile' });
  }
});

// Update current user's profile
router.put('/profile', authenticateToken, async (req, res) => {
  try {
    const { first_name, last_name, phone_number, email } = req.body;

    if (!first_name || !last_name || !phone_number || !email) {
      return res.status(400).json({ message: 'First name, last name, phone number, and email are required' });
    }

    // Check for duplicate email (excluding current user)
    const [existingUsers] = await query(
      'SELECT * FROM users WHERE email = ? AND id != ?',
      [email, req.user.userId]
    );
    if (existingUsers.length > 0) {
      return res.status(400).json({ message: 'Email already exists' });
    }

    const [result] = await query(
      'UPDATE users SET first_name = ?, last_name = ?, phone_number = ?, email = ? WHERE id = ?',
      [first_name, last_name, phone_number, email, req.user.userId]
    );

    if (result.affectedRows === 0) {
      return res.status(404).json({ message: 'User not found' });
    }

    const [users] = await query(
      'SELECT id, email, first_name, last_name, phone_number, admin FROM users WHERE id = ?',
      [req.user.userId]
    );

    res.json(users[0]);
  } catch (error) {
    console.error('Profile update error:', error);
    res.status(500).json({ message: 'Error updating user profile' });
  }
});

// Update current user's password
router.put('/profile/password', authenticateToken, async (req, res) => {
  try {
    const { currentPassword, newPassword } = req.body;

    if (!currentPassword || !newPassword) {
      return res.status(400).json({ message: 'Current and new passwords are required' });
    }

    // Optional: enforce minimum length manually too
    if (newPassword.length < 8) {
      return res.status(400).json({ message: 'New password must be at least 8 characters long' });
    }

    if (!validator.isStrongPassword(newPassword)) {
      return res.status(400).json({ message: 'Password must be strong (e.g., include uppercase, numbers, and symbols)' });
    }

    const [users] = await query(
      'SELECT password_hash FROM users WHERE id = ?',
      [req.user.userId]
    );

    if (users.length === 0) {
      return res.status(404).json({ message: 'User not found' });
    }

    const validPassword = await bcrypt.compare(currentPassword, users[0].password_hash);
    if (!validPassword) {
      return res.status(401).json({ message: 'Current password is incorrect' });
    }

    const isSamePassword = await bcrypt.compare(newPassword, users[0].password_hash);
    if (isSamePassword) {
      return res.status(400).json({ message: 'New password must be different from current password' });
    }

    const hashedPassword = await bcrypt.hash(newPassword, 10);
    await query(
      'UPDATE users SET password_hash = ? WHERE id = ?',
      [hashedPassword, req.user.userId]
    );

    res.json({ message: 'Password updated successfully' });

  } catch (error) {
    console.error('Password change error:', error);
    res.status(500).json({ message: 'Error changing password' });
  }
});

// Forgot password route
router.post('/forgot-password', async (req, res) => {
  try {
    const { email } = req.body;

    if (!email) {
      return res.status(400).json({ message: 'Email is required' });
    }

    // Check if user exists
    const [users] = await query('SELECT * FROM users WHERE email = ?', [email]);
    
    if (users.length === 0) {
      // Don't reveal if email exists or not for security
      return res.json({ message: 'If an account with that email exists, password reset instructions have been sent.' });
    }

    const user = users[0];
    
    // Generate a secure reset token
    const resetToken = generatePasswordResetToken();
    const resetTokenExpiry = new Date(Date.now() + 3600000); // 1 hour from now

    // Hash the token before storing in database
    const hashedResetToken = hashToken(resetToken);

    // Store hashed reset token in database
    await query(
      'UPDATE users SET reset_token = ?, reset_token_expiry = ? WHERE id = ?',
      [hashedResetToken, resetTokenExpiry, user.id]
    );

    // Generate reset URL
    const resetUrl = `${process.env.FRONTEND_URL || 'https://tayandtoscorporations.com'}/reset-password?token=${resetToken}`;

    try {
      // Send password reset email
      await sendPasswordResetEmail(user, resetToken, resetUrl);
      console.log(`Password reset email sent to ${email}`);
    } catch (emailError) {
      console.error('Error sending password reset email:', emailError);
      // Clear the token if email fails
      await query(
        'UPDATE users SET reset_token = NULL, reset_token_expiry = NULL WHERE id = ?',
        [user.id]
      );
      return res.status(500).json({ message: 'Error sending password reset email. Please try again.' });
    }

    res.json({ message: 'If an account with that email exists, password reset instructions have been sent.' });

  } catch (error) {
    console.error('Forgot password error:', error);
    res.status(500).json({ message: 'Error processing password reset request' });
  }
});

// Reset password route
router.post('/reset-password', async (req, res) => {
  try {
    const { token, newPassword } = req.body;

    if (!token || !newPassword) {
      return res.status(400).json({ message: 'Token and new password are required' });
    }

    // Validate password strength
    if (newPassword.length < 8) {
      return res.status(400).json({ message: 'Password must be at least 8 characters long' });
    }

    if (!validator.isStrongPassword(newPassword)) {
      return res.status(400).json({ message: 'Password must be strong (e.g., include uppercase, numbers, and symbols)' });
    }

    // Find user with valid hashed reset token
    const hashedToken = hashToken(token);
    const [users] = await query(
      'SELECT * FROM users WHERE reset_token = ? AND reset_token_expiry > NOW()',
      [hashedToken]
    );

    if (users.length === 0) {
      return res.status(400).json({ message: 'Invalid or expired reset token' });
    }

    const user = users[0];

    // Hash new password
    const hashedPassword = await bcrypt.hash(newPassword, 10);

    // Update password and clear reset token
    await query(
      'UPDATE users SET password_hash = ?, reset_token = NULL, reset_token_expiry = NULL WHERE id = ?',
      [hashedPassword, user.id]
    );

    // Send password reset confirmation email
    try {
      await sendPasswordResetConfirmationEmail(user);
      console.log(`Password reset confirmation email sent to ${user.email}`);
    } catch (emailError) {
      console.error('Error sending password reset confirmation email:', emailError);
      // Don't fail the password reset if email fails, but log the error
    }

    res.json({ message: 'Password has been reset successfully. A confirmation email has been sent to your email address.' });

  } catch (error) {
    console.error('Reset password error:', error);
    res.status(500).json({ message: 'Error resetting password' });
  }
});

// Get current user's bookings
router.get('/bookings', authenticateToken, async (req, res) => {
  try {
    const [bookings] = await query(`
      SELECT 
        booking_id as id, room, check_in_date, check_out_date, number_of_guests, status, special_requests, first_name, last_name, email, phone_number
      FROM bookings 
