        `SELECT * FROM guest_bookings 
         WHERE room = ? AND booking_id != ? AND status != 'cancelled'
         AND (check_in_date < ? AND check_out_date > ?)`,
        [room, booking.booking_id, check_out_date, check_in_date]
      );

      if (conflicts.length > 0) {
